[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Chocolate Retail Sales Performance Report 2023–2024</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --brown-dark: #3D1C02;
    --brown-mid: #6B3A2A;
    --brown-warm: #9C4F1A;
    --caramel: #C47A2E;
    --gold: #D4A84B;
    --cream: #FDF6EC;
    --light-bg: #F9F1E7;
    --border: #E5D5C0;
    --text-primary: #1A0E00;
    --text-secondary: #5A3D28;
    --text-muted: #8A6B52;
    --green: #2D7D46;
    --red: #C0392B;
    --blue: #2C5F8A;
    --blue-light: #EBF3FA;
    --shadow: 0 2px 12px rgba(61,28,2,0.10);
    --shadow-lg: 0 8px 32px rgba(61,28,2,0.14);
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--light-bg);
    color: var(--text-primary);
    line-height: 1.6;
    font-size: 15px;
  }

  /* ===== HEADER ===== */
  .report-header {
    background: linear-gradient(135deg, var(--brown-dark) 0%, var(--brown-mid) 60%, var(--brown-warm) 100%);
    color: white;
    padding: 56px 64px 48px;
    position: relative;
    overflow: hidden;
  }
  .report-header::before {
    content: '';
    position: absolute; top: 0; right: 0; bottom: 0;
    width: 40%;
    background: url("data:image/svg+xml,%3Csvg width='80' height='80' viewBox='0 0 80 80' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Cpath d='M0 0h40v40H0V0zm40 40h40v40H40V40zm0-40h2l-2 2V0zm0 4l4-4h2l-6 6V4zm0 4l8-8h2L40 10V8zm0 4L52 0h2L40 14v-2zm0 4L56 0h2L40 18v-2zm0 4L60 0h2L40 22v-2zm0 4L64 0h2L40 26v-2zm0 4L68 0h2L40 30v-2zm0 4L72 0h2L40 34v-2zm0 4L76 0h2L40 38v-2zm0 4L80 0v2L42 40h-2zm4 0L80 4v2L46 40h-2zm4 0L80 8v2L50 40h-2zm4 0L80 12v2L54 40h-2zm4 0L80 16v2L58 40h-2zm4 0L80 20v2L62 40h-2zm4 0L80 24v2L66 40h-2zm4 0L80 28v2L70 40h-2zm4 0L80 32v2L74 40h-2zm4 0L80 36v2L78 40h-2zm4 0L80 40v0h-2l2-2v2z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    opacity: 0.5;
  }
  .header-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2.5px;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 16px;
  }
  .header-title {
    font-size: 36px;
    font-weight: 700;
    line-height: 1.2;
    margin-bottom: 12px;
    letter-spacing: -0.5px;
  }
  .header-subtitle {
    font-size: 16px;
    color: rgba(255,255,255,0.75);
    margin-bottom: 32px;
  }
  .header-meta {
    display: flex;
    gap: 32px;
    font-size: 13px;
    color: rgba(255,255,255,0.6);
  }
  .header-meta span strong { color: rgba(255,255,255,0.9); }

  /* ===== LAYOUT ===== */
  .container { max-width: 1280px; margin: 0 auto; padding: 0 40px; }
  .section { padding: 56px 0 40px; }
  .section + .section { border-top: 1px solid var(--border); }

  .section-header { margin-bottom: 32px; }
  .section-tag {
    display: inline-block;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--caramel);
    background: rgba(196,122,46,0.10);
    padding: 4px 10px;
    border-radius: 4px;
    margin-bottom: 10px;
  }
  .section-title {
    font-size: 26px;
    font-weight: 700;
    color: var(--brown-dark);
    letter-spacing: -0.3px;
  }
  .section-desc {
    margin-top: 8px;
    font-size: 14px;
    color: var(--text-muted);
    max-width: 680px;
  }

  /* ===== KPI CARDS ===== */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 40px;
  }
  @media (max-width: 1100px) { .kpi-grid { grid-template-columns: repeat(3, 1fr); } }

  .kpi-card {
    background: white;
    border-radius: 12px;
    padding: 24px 20px 20px;
    box-shadow: var(--shadow);
    border: 1px solid var(--border);
    position: relative;
    overflow: hidden;
  }
  .kpi-card::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--caramel), var(--gold));
    border-radius: 12px 12px 0 0;
  }
  .kpi-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 10px;
  }
  .kpi-value {
    font-size: 28px;
    font-weight: 800;
    color: var(--brown-dark);
    letter-spacing: -1px;
    line-height: 1;
  }
  .kpi-sub {
    font-size: 12px;
    color: var(--text-muted);
    margin-top: 6px;
  }
  .kpi-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 11px;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 99px;
    margin-top: 8px;
  }
  .kpi-badge.up { background: #E8F5EE; color: var(--green); }
  .kpi-badge.neutral { background: var(--blue-light); color: var(--blue); }

  /* ===== CHARTS ===== */
  .chart-grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
  }
  .chart-grid-3 {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
  }
  .chart-card {
    background: white;
    border-radius: 12px;
    padding: 24px;
    box-shadow: var(--shadow);
    border: 1px solid var(--border);
  }
  .chart-card.full-width { grid-column: 1 / -1; }
  .chart-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--brown-dark);
    margin-bottom: 4px;
  }
  .chart-subtitle {
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 20px;
  }
  .chart-container { position: relative; }

  /* ===== TABLES ===== */
  .data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }
  .data-table th {
    text-align: left;
    padding: 10px 14px;
    background: var(--light-bg);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--text-muted);
    border-bottom: 2px solid var(--border);
  }
  .data-table td {
    padding: 10px 14px;
    border-bottom: 1px solid #F0E8DC;
    color: var(--text-secondary);
  }
  .data-table tr:hover td { background: var(--cream); }
  .data-table td.num { text-align: right; font-variant-numeric: tabular-nums; }
  .data-table td.rank {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    width: 36px;
  }
  .rank-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px; height: 22px;
    border-radius: 50%;
    font-size: 11px;
    font-weight: 800;
  }
  .rank-1 { background: #FFD700; color: #5A3D00; }
  .rank-2 { background: #C0C0C0; color: #3D3D3D; }
  .rank-3 { background: #CD7F32; color: white; }
  .rank-n { background: var(--light-bg); color: var(--text-muted); }

  .margin-bar {
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .margin-bar-fill {
    height: 6px;
    border-radius: 3px;
    background: linear-gradient(90deg, var(--caramel), var(--gold));
    min-width: 2px;
  }
  .margin-bar span { font-size: 12px; color: var(--text-muted); min-width: 42px; text-align: right; }

  /* ===== INSIGHT BOXES ===== */
  .insight-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 24px;
  }
  .insight-box {
    background: var(--cream);
    border: 1px solid var(--border);
    border-left: 4px solid var(--caramel);
    border-radius: 8px;
    padding: 16px 18px;
  }
  .insight-box.green { border-left-color: var(--green); }
  .insight-box.blue { border-left-color: var(--blue); }
  .insight-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-muted);
    margin-bottom: 6px;
  }
  .insight-text {
    font-size: 13px;
    color: var(--text-secondary);
    line-height: 1.5;
  }
  .insight-text strong { color: var(--text-primary); }

  /* ===== DISCOUNT SECTION ===== */
  .discount-visual {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
  }
  .discount-card {
    background: white;
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
    text-align: center;
    box-shadow: var(--shadow);
  }
  .discount-pct {
    font-size: 32px;
    font-weight: 900;
    color: var(--brown-dark);
    line-height: 1;
    margin-bottom: 4px;
  }
  .discount-orders {
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 12px;
  }
  .discount-stat {
    display: flex;
    justify-content: space-between;
    font-size: 12px;
    padding: 4px 0;
    border-top: 1px solid #F0E8DC;
  }
  .discount-stat-label { color: var(--text-muted); }
  .discount-stat-val { font-weight: 700; color: var(--text-secondary); }

  /* ===== CUSTOMER SECTION ===== */
  .customer-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  /* ===== SUMMARY CALLOUT ===== */
  .callout {
    background: linear-gradient(135deg, var(--brown-dark), var(--brown-mid));
    color: white;
    border-radius: 12px;
    padding: 28px 32px;
    margin-top: 24px;
  }
  .callout-title {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 12px;
  }
  .callout-points {
    list-style: none;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px 32px;
  }
  .callout-points li {
    font-size: 13px;
    color: rgba(255,255,255,0.85);
    padding-left: 16px;
    position: relative;
  }
  .callout-points li::before {
    content: '›';
    position: absolute; left: 0;
    color: var(--gold);
    font-weight: 700;
  }

  /* ===== FOOTER ===== */
  .report-footer {
    background: var(--brown-dark);
    color: rgba(255,255,255,0.5);
    padding: 24px 64px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 12px;
    margin-top: 40px;
  }
  .report-footer strong { color: rgba(255,255,255,0.8); }

  /* ===== YoY COMPARISON ===== */
  .yoy-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 28px;
  }
  .yoy-card {
    background: white;
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px 20px;
    box-shadow: var(--shadow);
  }
  .yoy-label { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); margin-bottom: 10px; }
  .yoy-vals { display: flex; gap: 12px; align-items: baseline; }
  .yoy-2023 { font-size: 18px; font-weight: 700; color: var(--text-muted); }
  .yoy-2024 { font-size: 22px; font-weight: 800; color: var(--brown-dark); }
  .yoy-arrow { font-size: 18px; color: var(--border); }
  .yoy-delta { font-size: 12px; font-weight: 700; margin-top: 6px; }
  .yoy-delta.up { color: var(--green); }
  .yoy-delta.flat { color: var(--blue); }

  .nav-pills {
    display: flex;
    gap: 8px;
    margin-bottom: 32px;
    padding: 16px 0 0;
    border-bottom: 2px solid var(--border);
  }
  .nav-pill {
    font-size: 13px;
    font-weight: 600;
    color: var(--text-muted);
    padding: 8px 16px;
    border-radius: 6px 6px 0 0;
    cursor: default;
    margin-bottom: -2px;
  }
  .nav-pill.active {
    color: var(--brown-dark);
    border-bottom: 2px solid var(--brown-dark);
  }
</style>
</head>
<body>

<!-- ===== HEADER ===== -->
<div class="report-header">
  <div class="container">
    <div class="header-label">Retail Management Report</div>
    <div class="header-title">Chocolate Retail Sales Performance Report</div>
    <div class="header-subtitle">Comprehensive analysis of sales trends, profitability, and customer behavior across the 2023–2024 period</div>
    <div class="header-meta">
      <span><strong>Period:</strong> January 2023 – December 2024</span>
      <span><strong>Transactions Analyzed:</strong> 50,000</span>
      <span><strong>Stores:</strong> 100</span>
      <span><strong>Prepared:</strong> April 2026</span>
    </div>
  </div>
</div>

<!-- ===== NAVIGATION ===== -->
<div class="container">
  <div class="nav-pills">
    <span class="nav-pill active">Executive Summary</span>
    <span class="nav-pill">Sales Trends</span>
    <span class="nav-pill">Products</span>
    <span class="nav-pill">Stores</span>
    <span class="nav-pill">Discounts</span>
    <span class="nav-pill">Customers</span>
  </div>
</div>

<!-- ===== 1. EXECUTIVE SUMMARY ===== -->
<div class="container">
  <div class="section" id="executive-summary">
    <div class="section-header">
      <div class="section-tag">Section 1</div>
      <div class="section-title">Executive Summary</div>
      <div class="section-desc">High-level performance snapshot across the 2023–2024 reporting period. All figures derived from 50,000 retail transactions across 100 stores.</div>
    </div>

    <!-- KPI Dashboard -->
    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="kpi-label">Total Revenue</div>
        <div class="kpi-value">$1.275M</div>
        <div class="kpi-sub">Across 50,000 transactions</div>
        <div class="kpi-badge up">▲ +1.72% YoY</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Total Profit</div>
        <div class="kpi-value">$510.5K</div>
        <div class="kpi-sub">Net of all product costs</div>
        <div class="kpi-badge up">▲ +1.57% YoY</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Profit Margin</div>
        <div class="kpi-value">40.03%</div>
        <div class="kpi-sub">Mean across all orders</div>
        <div class="kpi-badge neutral">Stable YoY</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Order Value</div>
        <div class="kpi-value">$25.51</div>
        <div class="kpi-sub">Per transaction</div>
        <div class="kpi-badge neutral">No discount: $27.15</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Discount Utilization</div>
        <div class="kpi-value">37.6%</div>
        <div class="kpi-sub">Of all transactions</div>
        <div class="kpi-badge neutral">3 tiers: 10/15/20%</div>
      </div>
    </div>

    <!-- YoY comparison -->
    <div class="yoy-row">
      <div class="yoy-card">
        <div class="yoy-label">Revenue</div>
        <div class="yoy-vals">
          <span class="yoy-2023">$632K</span>
          <span class="yoy-arrow">→</span>
          <span class="yoy-2024">$643K</span>
        </div>
        <div class="yoy-delta up">▲ +$10,870 (+1.72%)</div>
      </div>
      <div class="yoy-card">
        <div class="yoy-label">Profit</div>
        <div class="yoy-vals">
          <span class="yoy-2023">$253K</span>
          <span class="yoy-arrow">→</span>
          <span class="yoy-2024">$257K</span>
        </div>
        <div class="yoy-delta up">▲ +$3,968 (+1.57%)</div>
      </div>
